#!/usr/bin/env node
// Regenerates apps/main/lib/cron/canonical-fleet.embedded.ts from
// scripts/cron-fleet.json so the serverless fallback can never drift
// silently from the canonical fleet definition.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const raw = readFileSync(join(root, 'scripts/cron-fleet.json'), 'utf8');
JSON.parse(raw); // must be valid JSON
const ts = `/**
 * AUTOGENERATED from scripts/cron-fleet.json — do not edit by hand.
 * Regenerate with: node scripts/gen-fleet-snapshot.mjs
 *
 * Fallback copy of the canonical fleet for runtime environments where the
 * JSON file itself is not present on disk (minimal serverless bundles).
 * canonical-fleet.ts always PREFERS the real file via fs; a unit test
 * fails loudly if this snapshot ever drifts from the file.
 */
export const EMBEDDED_FLEET_JSON: string = ${JSON.stringify(raw)};
`;
writeFileSync(join(root, 'apps/main/lib/cron/canonical-fleet.embedded.ts'), ts);
console.log('canonical-fleet.embedded.ts regenerated from scripts/cron-fleet.json');
